                /* @ts-expect-error TS2554 -- this call omits trailing arguments the JS caller has always been able to omit */ if (scratchFBO) disposeScenePostFBO(gl, scratchFBO);
                scratchFBO = createScenePostFBO(gl, scaledW, scaledH);
